   if(result.getResultCode()!=RESULT_OK||result.getData()==null)return;ArrayList<Uri> uris=new ArrayList<>();Intent data=result.getData();
   if(data.getClipData()!=null)for(int i=0;i<data.getClipData().getItemCount();i++)uris.add(data.getClipData().getItemAt(i).getUri());else if(data.getData()!=null)uris.add(data.getData());importImages(uris);
