 final class CameraOverlay extends View{
  Vision.Result result;int fw=480,fh=640;Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);final Path contour=new Path();final DashPathEffect guideDash=new DashPathEffect(new float[]{dp(8),dp(6)},0);final float[] guidePaper=options.size();
  CameraOverlay(Context c){super(c);setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);}
  protected void onDraw(Canvas c){
   float s=Math.min(getWidth()/(float)fw,getHeight()/(float)fh),w=fw*s,h=fh*s,x=(getWidth()-w)/2,y=(getHeight()-h)/2;paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(dp(2));
   if(result!=null&&result.corners!=null){paint.setColor(0xffdc7852);Path p=contour;p.reset();for(int i=0;i<4;i++){float px=x+result.corners[i*2]*w,py=y+result.corners[i*2+1]*h;if(i==0)p.moveTo(px,py);else p.lineTo(px,py);}p.close();c.drawPath(p,paint);paint.setStyle(Paint.Style.FILL);for(int i=0;i<4;i++)c.drawCircle(x+result.corners[i*2]*w,y+result.corners[i*2+1]*h,dp(4),paint);}
   else{float[] paper=guidePaper;float gw=Math.min(w*.78f,h*.78f*paper[0]/paper[1]),gh=gw*paper[1]/paper[0];paint.setColor(0x99ffffff);paint.setPathEffect(guideDash);c.drawRect((getWidth()-gw)/2,(getHeight()-gh)/2,(getWidth()+gw)/2,(getHeight()+gh)/2,paint);paint.setPathEffect(null);}
  }
 }
